export interface Ssh {
  /**
   * SSH username
   */
  username: string;
  /**
   * SSH password
   */
  password?: string;
  /**
   * SSH private key
   */
  "private-key"?: string;
}
/**
 * Configuration for an external (push-based) endpoint
 *
 * This interface was referenced by `ApplicationDefinitionSchema`'s JSON-Schema
 * via the `definition` "externalEndpoint".
 */
export interface ExternalEndpoint {
  /**
   * Whether the endpoint is enabled
   */
  enabled?: boolean;
  /**
   * Name of the endpoint
   */
  name: string;
  /**
   * Group to which the endpoint belongs
   */
  group?: string;
  /**
   * Bearer token required to push results to this endpoint
   */
  token: string;
  /**
   * Alerts to trigger on failure
   */
  alerts?: Alert[];
  /**
   * Per-endpoint maintenance windows. During a window the endpoint does not alert.
   */
  "maintenance-windows"?: MaintenanceWindow[];
  /**
   * Heartbeat configuration for detecting when the external endpoint stops pushing results
   */
  heartbeat?: {
    /**
     * Expected interval between pushes. If no result arrives within it, the endpoint fails. Must be at least 10s
     */
    interval?: string;
  };
}
